// Report account balances from a ledger file.

const encoder = new TextEncoder();

function to_cents(amount: string): bigint {
  const [whole, fraction = ""] = amount.split(".");
  return BigInt(whole || "0") * 100n + BigInt((fraction + "00").slice(0, 2));
}

function format_cents(cents: bigint): string {
  const sign = cents < 0n ? "-" : "";
  const abs = cents < 0n ? -cents : cents;
  const fraction = String(abs % 100n).padStart(2, "0");
  return `${sign}${abs / 100n}.${fraction}`;
}

function compare_bytes(left: string, right: string): number {
  const a = encoder.encode(left);
  const b = encoder.encode(right);
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return a.length - b.length;
}

function by_balance(left: [string, bigint], right: [string, bigint]): number {
  if (left[1] != right[1]) return left[1] > right[1] ? -1 : 1;
  return compare_bytes(left[0], right[0]);
}

function main() {
  const lines = Deno.readTextFileSync(Deno.args[0]).split(/\r?\n/);
  const n = Number(lines[0].trim().split(/\s+/)[1]);

  const balances = new Map<string, bigint>();
  for (let index = 0; index < n; index++) {
    const [account, kind, amount] = (lines[1 + index] ?? "").trim().split(/\s+/);
    if (kind != "debit" && kind != "credit") {
      console.log(`ERROR line ${index + 1}`);
      return;
    }
    const cents = to_cents(amount);
    const signed = kind == "credit" ? cents : -cents;
    balances.set(account, (balances.get(account) ?? 0n) + signed);
  }

  const entries = [...balances.entries()].sort(by_balance);
  let total = 0n;
  for (const [account, balance] of entries) {
    console.log(`${account} ${format_cents(balance)}`);
    total += balance;
  }
  console.log(`TOTAL ${format_cents(total)}`);
}

main();
